```js
(async () => {
  const base = 'https://www.gsmarena.com/';
  const norm = s => (s||'').toLowerCase().replace(/[^a-z0-9]/g,'');
  const searchUrl = term => base + 'res.php3?sSearch=' + encodeURIComponent(term);
  const out = {};
  const jobs = [['ip','Apple iPhone 17 Pro'],['px','Google Pixel 10 Pro'],['ss','Samsung Galaxy S25 Ultra']];
  for (const [key, full] of jobs) {
    try {
      const r = await fetch(searchUrl(full), {headers:{'X-Requested-With':'fetch'}});
      const t = await r.text();
      const doc = new DOMParser().parseFromString(t, 'text/html');
      const links = [...doc.querySelectorAll('.makers a')];
      const target = norm(full);
      let hit = links.find(a => norm(a.textContent) === target) || links.find(a => norm(a.textContent).includes(target));
      if (!hit) { out[key] = {error:'search-failed', sample: links.slice(0,5).map(a=>a.textContent.trim())}; continue; }
      const url = base + hit.getAttribute('href');
      const r2 = await fetch(url);
      const t2 = await r2.text();
      const d2 = new DOMParser().parseFromString(t2, 'text/html');
      const rows = [...d2.querySelectorAll('#specs-list tr')].map(tr => {
        const k = tr.querySelector('.ttl'); const v = tr.querySelector('.nfo');
        return k && v ? [k.textContent.trim(), v.textContent.trim().replace(/\s+/g,' ')] : null;
      }).filter(Boolean);
      const get = (k, n=0) => { const all = rows.filter(r=>r[0]===k); return all[n] ? all[n][1] : null; };
      out[key] = {
        url,
        title: (d2.querySelector('h1')||{}).textContent?.trim(),
        announced: get('Announced'), status: get('Status'),
        dims: get('Dimensions'), weight: get('Weight'), build: get('Build'), sim: get('SIM'),
        displayType: get('Type',0), displaySize: get('Size'), res: get('Resolution'), protection: get('Protection'),
        chipset: get('Chipset'), cpu: get('CPU'), gpu: get('GPU'), os: get('OS'),
        variants: get('Variants') || get('Internal'), card: get('Card slot'),
        mainCam: get('Triple') || get('Quad') || get('Dual') || get('Single',0),
        camFeat: get('Features',0), camVideo: get('Video',0),
        selfie: get('Single',1) || get('Under display'), selfieFeat: get('Features',1), selfieVideo: get('Video',1),
        battery: get('Type',1), charging: get('Charging'),
        sensors: get('Sensors'), colors: get('Colors'), price: get('Price'), models: get('Models'),
      };
    } catch(e) { out[key] = {error: String(e)}; }
  }
  return JSON.stringify(out, null, 1);
})()
```

